CREATE TYPE "LedgerAccountType" AS ENUM ('ASSET','LIABILITY','EQUITY','INCOME','EXPENSE');
CREATE TYPE "JournalStatus" AS ENUM ('DRAFT','POSTED','REVERSED');
CREATE TYPE "FinanceRecordKind" AS ENUM ('ASSET','BUDGET','TAX','PAYROLL');
CREATE TABLE "LedgerAccount" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"type" "LedgerAccountType" NOT NULL,"description" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"isSystem" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "LedgerAccount_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Journal" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"number" TEXT NOT NULL,"journalDate" DATE NOT NULL,"description" TEXT NOT NULL,"status" "JournalStatus" NOT NULL DEFAULT 'DRAFT',"lines" JSONB NOT NULL,"total" DECIMAL(19,4) NOT NULL,"reversedJournalId" UUID,"postedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Journal_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FinanceRecord" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"kind" "FinanceRecordKind" NOT NULL,"reference" TEXT NOT NULL,"name" TEXT NOT NULL,"startDate" DATE NOT NULL,"endDate" DATE,"amount" DECIMAL(19,4) NOT NULL,"status" TEXT NOT NULL,"data" JSONB NOT NULL DEFAULT '{}',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "FinanceRecord_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "LedgerAccount_organizationId_code_key" ON "LedgerAccount"("organizationId","code"); CREATE INDEX "LedgerAccount_organizationId_type_isActive_idx" ON "LedgerAccount"("organizationId","type","isActive");
CREATE UNIQUE INDEX "Journal_organizationId_number_key" ON "Journal"("organizationId","number"); CREATE INDEX "Journal_organizationId_status_journalDate_idx" ON "Journal"("organizationId","status","journalDate");
CREATE UNIQUE INDEX "FinanceRecord_organizationId_kind_reference_key" ON "FinanceRecord"("organizationId","kind","reference"); CREATE INDEX "FinanceRecord_organizationId_kind_status_idx" ON "FinanceRecord"("organizationId","kind","status");
ALTER TABLE "LedgerAccount" ADD CONSTRAINT "LedgerAccount_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Journal" ADD CONSTRAINT "Journal_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "FinanceRecord" ADD CONSTRAINT "FinanceRecord_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
